scan_linter_check.script:
(function(engine) {
    global.EcsGlideRecord.runBulkCheck(engine, {
        ruleId: 'SN-GR-003',
        tier: 'confirmed',
        bulkMethod: 'updateMultiple',
        perRecordMethod: 'update',
        title: 'GlideRecord update with no query conditions',
        recommendation: 'Add query conditions that limit the update to the intended records, and test them with ' +
            'a count (GlideAggregate) first. If updating every record really is intended, mute this finding with a reason.'
    });
})(engine);
